### C Implementation

```c
#include <stdio.h>
#include <string.h>

/**
 * reverse_string_inplace - Reverses a null-terminated string in place.
 *
 * @str: A pointer to the null-terminated string to be reversed.
 *
 * Return: A pointer to the now reversed string (the same pointer passed in).
 */
char* reverse_string_inplace(char* str) {
    if (str == NULL) {
        return NULL;
    }

    // 1. Initialize pointers for the start and end of the string
    char* start = str;
    char* end = str;

    // 2. Find the end of the string (the null terminator '\0')
    while (*end != '\0') {
        end++;
    }
    // 'end' now points to the null terminator. We need to move it back one
    // position to point to the last actual character.
    end--;

    // 3. Swap characters from the start and end pointers until they meet or cross
    while (start < end) {
        // Swap the characters
        char temp = *start;
        *start = *end;
        *end = temp;

        // Move pointers towards the center
        start++;
        end--;
    }

    return str;
}

// --- Example Usage ---
int main() {
    // Test Case 1: Normal string
    char s1[] = "hello world";
    printf("Original string 1: \"%s\"\n", s1);
    reverse_string_inplace(s1);
    printf("Reversed string 1: \"%s\"\n\n", s1);

    // Test Case 2: Palindrome (should remain the same)
    char s2[] = "madam";
    printf("Original string 2: \"%s\"\n", s2);
    reverse_string_inplace(s2);
    printf("Reversed string 2: \"%s\"\n\n", s2);

    // Test Case 3: Empty string
    char s3[] = "";
    printf("Original string 3: \"%s\"\n", s3);
    reverse_string_inplace(s3);
    printf("Reversed string 3: \"%s\"\n\n", s3);

    // Test Case 4: Single character string
